node --input-type=module <<'NODE'
import {readJson,writeJson,deploymentRoot} from './classic/scripts/local-production/common.mjs';
import {join} from 'node:path';
const candidate=await readJson(join(deploymentRoot,'candidate.json'));
if(candidate.id!=='2026-10-28T04-26-12-312Z-7f86ffec') throw Error('Unexpected candidate');
await writeJson(join(deploymentRoot,'previous.json'),await readJson(join(deploymentRoot,'current.json')));
await writeJson(join(deploymentRoot,'current.json'),candidate);
console.log(candidate.id);
